// isoparametric-curve: three isoparametric curves in the U direction on a quarter torus, and its periodicity
export function c004(context is Context, id is Id)
{
    const profile = newSketchOnPlane(context, id + "profile", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, -1, 0), vector(1, 0, 0)) });
    skCircle(profile, "c1", { "center" : vector(20, 0) * millimeter, "radius" : 5 * millimeter });
    skSolve(profile);
    const axis = newSketchOnPlane(context, id + "axis", { "sketchPlane" : plane(vector(0, 0, -50) * millimeter, vector(0, 1, 0), vector(0, 0, 1)) });
    skLineSegment(axis, "line1", { "start" : vector(0, 0) * millimeter, "end" : vector(100, 0) * millimeter });
    skSolve(axis);
    revolve(context, id + "base", { "entities" : qSketchRegion(id + "profile"), "axis" : qCreatedBy(id + "axis", EntityType.EDGE), "fullRevolve" : false, "endBound" : RevolveBoundingType.BLIND, "oppositeDirection" : false, "angle" : 90 * degree });
    isoparametricCurve(context, id + "curve1", { "face" : qGeometry(qOwnedByBody(qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID), EntityType.FACE), GeometryType.TORUS), "directionType" : DirectionType.U_DIRECTION, "equalSpacing" : true, "nCurves" : 3 });
    return { "periodicity" : [evFacePeriodicity(context, { "face" : qGeometry(qOwnedByBody(qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID), EntityType.FACE), GeometryType.TORUS) }), evFacePeriodicity(context, { "face" : qGeometry(qOwnedByBody(qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID), EntityType.FACE), GeometryType.TORUS), "trimmed" : false })], "curves" : edgePoints(context, qCreatedBy(id + "curve1", EntityType.BODY)) };
}

