// fillet: a variable fillet, 2 mm to 5 mm along a block's top edge, curvature (magnitude 0.5)
export function c006(context is Context, id is Id)
{
    const baseSketch = newSketchOnPlane(context, id + "baseSketch", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skRectangle(baseSketch, "rect1", { "firstCorner" : vector(0, 0) * millimeter, "secondCorner" : vector(40, 30) * millimeter });
    skSolve(baseSketch);
    extrude(context, id + "base", { "entities" : qSketchRegion(id + "baseSketch"), "endBound" : BoundingType.BLIND, "depth" : 12 * millimeter });
    fillet(context, id + "fillet1", { "entities" : qContainsPoint(qOwnedByBody(qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID), EntityType.EDGE), vector(20, 0, 12) * millimeter), "radius" : 3 * millimeter, "isVariable" : true, "vertexSettings" : [{ "vertex" : qContainsPoint(qOwnedByBody(qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID), EntityType.VERTEX), vector(0, 0, 12) * millimeter), "vertexRadius" : 2 * millimeter, "variableMagnitude" : 0.5 }, { "vertex" : qContainsPoint(qOwnedByBody(qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID), EntityType.VERTEX), vector(40, 0, 12) * millimeter), "vertexRadius" : 5 * millimeter, "variableMagnitude" : 0.5 }], "crossSection" : FilletCrossSection.CURVATURE, "nonCircularRadius" : 3 * millimeter, "magnitude" : 0.5, "smoothTransition" : true });
    return { "faces" : faceProbe(context, qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID)) };
}

